@pytest.mark.parametrize('size', [-2, -2., -0.2, 0, 0.,
                                 np.int32(-2), np.float32(-0.2),
                                 1., 2., 100, 101])
@pytest.mark.parametrize('size_name', ['train_size', 'test_size'])
@pytest.mark.parametrize('splitter', [ShuffleSplit, StratifiedShuffleSplit,
                                    GroupShuffleSplit])
def test_shuffle_split_invalid_sizes(size, size_name, splitter):
    sizes = {'train_size': None, 'test_size': None}
    sizes[size_name] = size
    X = np.arange(100)
    with pytest.raises(ValueError, match=size_name):
        next(splitter(**sizes).split(X, X % 2, groups=X))


